args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Ferdinand_I_of_the_Two_Sicilies ?p ?father .
  FILTER(?p IN (dbo:parent, dbp:father, dbo:father, dbp:parent))
  FILTER(isIRI(?father))
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
