SELECT DISTINCT ?father ?fatherLabel WHERE {
  { dbr:Ferdinand_I_of_the_Two_Sicilies dbp:father ?father } UNION { dbr:Ferdinand_I_of_the_Two_Sicilies dbo:father ?father }
  FILTER(isIRI(?father))
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

